@testset "Gamma SD target, objective and frozen derivatives" begin
    f = bf(@formula(y ~ x + (1 | g)), @formula(sigma ~ x))
    prior(a=2., b=3.; group="g") = drm_priors(drm_prior_sd_gamma(dpar="mu", group=group, shape=a, rate=b))
    @test_throws ArgumentError drm_prior_sd_gamma(dpar="sigma", group="g", shape=2, rate=3)
    @test_throws ArgumentError drm_prior_sd_gamma(dpar="mu", group="g", coef="x", shape=2, rate=3)
    for (a,b) in ((1.,3.), (Inf,3.), (2.,0.), (2.,Inf), (NaN,1.))
        @test_throws ArgumentError drm_prior_sd_gamma(dpar="mu", group="g", shape=a, rate=b)
    end
    dat = (y=ORACLE_CASES[1], x=ORACLE_X, g=ORACLE_GROUP)
    row = only(resolve_priors(f, Gaussian(); data=dat, priors=prior()))
    @test (row.class,row.dpar,row.group,row.block,row.coef,row.scale,row.shape,row.rate) == (:random_effect_sd,:mu,"g",:iid_intercept,"(Intercept)",:sd,2.,3.)
    @test_throws ArgumentError resolve_priors(f, Gaussian(); data=dat, priors=prior(group="wrong"))
    @test_throws ArgumentError drm(f, Gaussian(); data=dat, priors=prior(group="wrong"))
    p=drm_prior_sd_gamma(dpar="mu",group="g",shape=2,rate=3)
    @test_throws ArgumentError resolve_priors(f,Gaussian(); data=dat,priors=drm_priors(p,p))
    @test_throws ArgumentError drm(bf(@formula(y ~ x)), Gaussian(); data=dat, priors=prior())
    @test_throws ArgumentError drm(f, Gaussian(); data=dat, priors=prior(), method=:REML)
    @test_throws ArgumentError drm(f, Gaussian(); data=dat, priors=prior(), weights=fill(2.,9))
    θ = [0.,0.,0.,0.,log(.8)]
    @test DRModels._sd_prior_value(row,θ) ≈ 0.425918974 atol=1e-9
    @test ForwardDiff.derivative(t -> DRModels._sd_prior_value(row,[0.,0.,0.,0.,t]), log(1/3)) ≈ 0 atol=1e-12
    fits = Dict()
    for (a,b,refs) in ((2.,3.,ORACLE_0),(2.5,1.7,ORACLE_1))
        for case in 1:3
            data = (y=ORACLE_CASES[case],x=ORACLE_X,g=ORACLE_GROUP)
            fit = drm(f, Gaussian(); data=data, priors=prior(a,b))
            fits[(case,a,b)] = fit
            @test fit.estim_method == :MAP
            @test fit.loglik ≈ -fit.penalty.data_nll(fit.theta) atol=1e-9
            @test fit.nll(fit.theta) ≈ -fit.loglik + fit.penalty.fixed_penalty + fit.penalty.sd_penalty atol=1e-9
            for (c,pt,obj,grad,hess) in refs
                c == case || continue
                q=ORACLE_POINTS[pt]
                @test abs(fit.nll(q)-obj) <= 1e-8 * max(1,abs(obj))
                @test maximum(abs.(ForwardDiff.gradient(fit.nll,q) .- grad)) <= 1e-6
                @test all(abs.(ForwardDiff.hessian(fit.nll,q) .- hess) .<= 1e-5 .* max.(1,abs.(hess)))
            end
        end
    end
    for (case,a,b,reference,obj,eligible) in ORACLE_OPTS
        fit=fits[(case,a,b)]
        score=maximum(abs,ForwardDiff.gradient(fit.nll,fit.theta))
        @test isfinite(score)
        @info "oracle optimum comparison" case a b oracle_success_and_eligible=eligible julia_converged=fit.converged score objective=fit.nll(fit.theta) oracle_objective=obj
        if eligible && fit.converged && score <= 1e-6
            @test fit.theta ≈ reference atol=1e-5
        else
            @test abs(fit.nll(fit.theta)-obj) <= 1e-7*max(1,abs(obj))
            @test isfinite(score) && score <= 1e-6
        end
    end
    mixed=drm_priors(drm_prior_normal(dpar="mu",coef="x",mean=.2,sd=2.),p)
    mf=drm(f,Gaussian(); data=dat,priors=mixed)
    @test mf.penalty.fixed_penalty > 0 && mf.penalty.sd_penalty > 0
    @test mf.nll(mf.theta) ≈ -mf.loglik + mf.penalty.fixed_penalty + mf.penalty.sd_penalty
    refit=update(mf,mf.formula; data=dat)
    @test refit.theta ≈ mf.theta atol=1e-6
    @test refit.penalty.sd_row == mf.penalty.sd_row
    reverse_mixed=drm_priors(p,drm_prior_normal(dpar="mu",coef="x",mean=.2,sd=2.))
    reversed_fit=drm(f,Gaussian();data=dat,priors=reverse_mixed)
    @test reversed_fit.penalty.specs == reverse_mixed
    @test update(reversed_fit,reversed_fit.formula;data=dat).penalty.specs == reverse_mixed
    @test_throws ArgumentError aic(mf)
    @test_throws ArgumentError bic(mf)
    @test_throws ArgumentError confint(mf)
    @test_throws ArgumentError profile_result(mf)
    @test_throws ArgumentError profile_curve(mf,1)
    @test_throws ArgumentError parameter_surface(mf,1,2)
    @test_throws ArgumentError simulate(mf)
    @test_throws ArgumentError predict(mf,dat; se=true)
    @test all(col -> all(isnan,col), coeftable(mf).cols[3:6])
end

@testset "Boundary, units, mutation controls and active guards" begin
    data=(y=ORACLE_CASES[1],x=ORACLE_X,g=ORACLE_GROUP)
    f=bf(@formula(y ~ x + (1 | g)), @formula(sigma ~ x))
    p=drm_prior_sd_gamma(dpar="mu",group="g",shape=2.,rate=3.)
    fit=drm(f,Gaussian();data=data,priors=drm_priors(p))
    q=copy(ORACLE_POINTS[1]); row=fit.penalty.sd_row
    pen=DRModels._sd_prior_value(row,q)
    @test abs(pen + q[end] - pen) > 1e-6 # added Jacobian
    @test abs((2exp(q[end])-2q[end]-3log(2)+log(2))-pen) > 1e-6 # swapped parameters
    @test abs(pen - (pen + 2log(3))) > 1e-6 # omitted normalizer
    @test abs(pen) > 1e-6 && abs(2pen-pen) > 1e-6 && abs(3pen-pen) > 1e-6
    for eta in (-20.,-40.)
        q[end]=eta
        @test fit.nll(q) > fit.penalty.data_nll(q)
        @test ForwardDiff.gradient(fit.nll,q)[end] ≈ -1 atol=1e-6
        @test abs(ForwardDiff.hessian(fit.nll,q)[end,end]) < 1e-6
    end
    # Limit of the unpenalized data density is the exact diagonal covariance.
    q[end]=-40
    r=data.y .- (q[1] .+ q[2].*data.x)
    sd=exp.(q[3] .+ q[4].*data.x)
    boundary=sum(log.(sd) .+ .5 .* (r./sd).^2) + length(r)*.5log(2π)
    @test fit.penalty.data_nll(q) ≈ boundary atol=1e-10
    c=2.4
    scaled=(y=c.*data.y,x=data.x,g=data.g)
    ps=drm_prior_sd_gamma(dpar="mu",group="g",shape=2.,rate=3/c)
    fs=drm(f,Gaussian();data=scaled,priors=drm_priors(ps))
    q=copy(ORACLE_POINTS[2]); qs=copy(q); qs[1:2].*=c; qs[3]+=log(c); qs[5]+=log(c)
    @test fs.nll(qs) ≈ fit.nll(q)+(length(data.y)+1)*log(c) atol=1e-8
    transform=Diagonal([1/c,1/c,1.,1.,1.])
    @test ForwardDiff.gradient(fs.nll,qs) ≈ transform*ForwardDiff.gradient(fit.nll,q) atol=1e-7
    @test ForwardDiff.hessian(fs.nll,qs) ≈ transform*ForwardDiff.hessian(fit.nll,q)*transform atol=1e-7
    zero=drm_prior_ridge(dpar="mu",coef="x",lambda=0.)
    z=drm(f,Gaussian();data=data,priors=drm_priors(zero,p))
    @test z.estim_method == :MAP
    @test z.penalty.fixed_penalty == 0
    @test_throws ArgumentError aic(z)
    err = try aic(z); nothing catch e; e end
    @test occursin("SD-prior", sprint(showerror, err))
    @test_throws ArgumentError confint(z)
    @test_throws ArgumentError simulate(z)
    floorq=copy(ORACLE_POINTS[1]); floorq[end]=-20.
    @test !DRModels._sd_prior_stationary(ForwardDiff.gradient(fit.nll,floorq))
    tiny=only(resolve_priors(f,Gaussian();data=data,priors=drm_priors(drm_prior_sd_gamma(dpar="mu",group="g",shape=1+1e-9,rate=3.))))
    underflowq=copy(floorq); underflowq[end]=-400.
    @test abs(ForwardDiff.derivative(t -> DRModels._sd_prior_value(tiny,[0.,0.,0.,0.,t]),underflowq[end])) < 1e-6
    @test !DRModels._sd_prior_interior(underflowq[end])
    @test !fit.converged || maximum(abs,ForwardDiff.gradient(fit.nll,fit.theta)) <= 1e-6
    plain=drm(f,Gaussian();data=data)
    @test plain.estim_method == :ML
    @test plain.penalty === nothing
    @test_throws ArgumentError lrtest(plain,z)
    @test_throws ArgumentError DRModels._bootstrap_refit_kwargs(z)
    @test_throws ArgumentError predict_parameters(z,data; se=true)
    @test_throws ArgumentError drm(f,Gaussian(); data=merge(data,(y=Union{Missing,Float64}[missing; data.y[2:end]],)),priors=drm_priors(p))
    @test_throws ArgumentError drm(bf(@formula(y ~ x + (1 + x | g)),@formula(sigma ~ x)),Gaussian();data=data,priors=drm_priors(p))
    @test_throws ArgumentError drm(bf(@formula(y ~ x + (1 | g) + (1 | h)),@formula(sigma ~ x)),Gaussian();data=merge(data,(h=data.g,)),priors=drm_priors(p))
    @test_throws ArgumentError update(fit,bf(@formula(y ~ x + (1 | wrong)),@formula(sigma ~ x));data=merge(data,(wrong=data.g,)))
end

@testset "SD priors reject missing predictors before row dropping" begin
    dat=(y=ORACLE_CASES[1],x=Union{Missing,Float64}[missing; ORACLE_X[2:end]],g=ORACLE_GROUP)
    f=bf(@formula(y ~ x + (1 | g)), @formula(sigma ~ x))
    p=drm_priors(drm_prior_sd_gamma(dpar="mu",group="g",shape=2.,rate=3.))
    @test_logs min_level=Logging.Warn @test_throws ArgumentError resolve_priors(f,Gaussian();data=dat,priors=p)
    @test_logs min_level=Logging.Warn @test_throws ArgumentError drm(f,Gaussian();data=dat,priors=p)
end

@testset "Prior abstraction and forged target refusal" begin
    dat=(y=ORACLE_CASES[1],x=ORACLE_X,g=ORACLE_GROUP)
    f=bf(@formula(y ~ x + (1 | g)), @formula(sigma ~ x))
    fixed=drm_prior_ridge(dpar="mu",coef="x",lambda=1.)
    sd=drm_prior_sd_gamma(dpar="mu",group="g",shape=2.,rate=3.)
    @test fixed isa DRModels.AbstractDrmPrior
    @test sd isa DRModels.AbstractDrmPrior
    for bad in (DRModels.SDGammaPrior(:sigma,"g","(Intercept)",2.,3.),
                DRModels.SDGammaPrior(:mu,"g","x",2.,3.),
                DRModels.SDGammaPrior(:mu,"g","(Intercept)",1.,3.),
                DRModels.SDGammaPrior(:mu,"g","(Intercept)",2.,Inf))
        @test_throws ArgumentError resolve_priors(f,Gaussian();data=dat,priors=drm_priors(bad))
        @test_throws ArgumentError drm(f,Gaussian();data=dat,priors=drm_priors(bad))
    end
    fit=drm(f,Gaussian();data=dat,priors=drm_priors(sd))
    fit.penalty.specs[1]=DRModels.SDGammaPrior(:sigma,"g","(Intercept)",2.,3.)
    @test_throws ArgumentError update(fit,fit.formula;data=dat)
end
